using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using System.Threading.Tasks;
using System.Windows;
using System.Windows.Controls;
using AirBridge.UI;
using AirBridge.Platform;
namespace AirBridge.Desktop {
 internal sealed class BatteryRecord {public string Key;public int Level=-1,Cached=-1;public DateTime ReadAt;public string LastStatus="";public bool Failed=true;public int Failures;public DateTime Next;public Task<PhoneBatteryReading> Pending;}
 internal sealed partial class MainView {
  readonly Dictionary<string,BatteryGauge[]> batteryViews=new Dictionary<string,BatteryGauge[]>();
  readonly Dictionary<string,BatteryRecord> batteries=new Dictionary<string,BatteryRecord>();
  readonly Dictionary<string,int[]> deviceLevels=new Dictionary<string,int[]>();
  readonly Dictionary<string,DateTime[]> deviceBatteryTimes=new Dictionary<string,DateTime[]>();
  DateTime batterySaved;bool headsetCacheDirty;
  sealed class HeadsetCache {public string Id;public int[] Levels;public DateTime[] Times;}
  void LoadHeadsetBatteries(){try{string path=Path.Combine(settings.Root,"headset-battery.json");if(!File.Exists(path))return;foreach(var item in SettingsStore.Json.Deserialize<HeadsetCache[]>(File.ReadAllText(path))){if(String.IsNullOrEmpty(item.Id)||item.Levels==null||item.Times==null||item.Levels.Length!=3||item.Times.Length!=3||item.Levels.Any(n=>n< -1||n>100)||item.Times.Any(t=>t>DateTime.UtcNow))continue;deviceLevels[item.Id]=item.Levels;deviceBatteryTimes[item.Id]=item.Times;}}catch(Exception ex){Log(ex.Message);}}
  void SaveHeadsetBatteries(DateTime now){if(settings.Test||!headsetCacheDirty||(now-batterySaved).TotalSeconds<30)return;try{SettingsStore.AtomicWrite(Path.Combine(settings.Root,"headset-battery.json"),SettingsStore.Json.Serialize(deviceLevels.Where(p=>deviceBatteryTimes.ContainsKey(p.Key)).Select(p=>new HeadsetCache{Id=p.Key,Levels=p.Value,Times=deviceBatteryTimes[p.Key]}).ToArray()));headsetCacheDirty=false;batterySaved=now;}catch(Exception ex){Log(ex.Message);}}
  readonly Dictionary<string,DateTime> podSeen=new Dictionary<string,DateTime>();
  readonly Dictionary<string,int> systemLevels=new Dictionary<string,int>();string batteryCandidate="",proximityCandidate="";DateTime batteryCandidateAt,proximityAt;
  readonly HashSet<string> lowWarned=new HashSet<string>();
  UIElement NewBattery(string id,string[] labels){var panel=new StackPanel{Orientation=Orientation.Horizontal};var gauges=labels.Select(label=>new BatteryGauge{Label=label,Width=label.Length==0?48:68,Height=24}).ToArray();foreach(var g in gauges){g.SetResourceReference(Control.ForegroundProperty,"Brush_344054");panel.Children.Add(g);}batteryViews[id]=gauges;return panel;}
  void LoadBatteries(){try{string path=Path.Combine(settings.Root,"phone-battery.json");if(!File.Exists(path))return;string json=File.ReadAllText(path).Trim();var records=SettingsStore.Json.Deserialize<BatteryRecord[]>(json.StartsWith("[")?json:"["+json+"]");foreach(var r in records){if(r.Level<0||r.Level>100||r.ReadAt.Year<2020||r.ReadAt.ToUniversalTime()>DateTime.UtcNow||String.IsNullOrEmpty(r.Key))continue;r.ReadAt=r.ReadAt.ToUniversalTime();r.Failed=true;batteries[r.Key]=r;}}catch(Exception ex){Log(ex.Message);}}
  void SaveBatteries(){if(settings.Test)return;try{SettingsStore.AtomicWrite(Path.Combine(settings.Root,"phone-battery.json"),SettingsStore.Json.Serialize(batteries.Values.Where(r=>r.Level>=0).Select(r=>new{r.Key,r.Level,ReadAt=r.ReadAt.ToString("o")}).ToArray()));}catch(Exception ex){Log(ex.Message);}}
  string BatteryUnavailable(string status){if(status=="paired-device-not-found")return L("Windows 未提供电量，也未找到匹配的低功耗蓝牙电量接口；音频连接正常不代表支持电量读取。","Windows provides no battery value or matching paired BLE battery interface; audio connectivity does not imply battery support.");if(status=="no-battery-service")return L("此设备未提供标准蓝牙电量服务。","This device does not expose the standard Bluetooth battery service.");return L("暂未读到电量，后台将自动重试。","Battery unavailable; retrying in the background.");}
  void TickBatteries(){DateTime now=DateTime.UtcNow;foreach(var r in batteries.Values.ToArray()){if(r.Pending==null||!r.Pending.IsCompleted)continue;PhoneBatteryReading read=null;try{read=r.Pending.GetAwaiter().GetResult();}catch(Exception ex){Log(ex.Message);}r.Pending=null;string status=read==null?"unavailable":read.Status;if(r.LastStatus!=status)Log("Phone battery "+r.Key+" status="+status+" stage="+(read==null?"unknown":read.Stage));r.LastStatus=status;if(read!=null&&read.Status=="live"&&read.Level>=0&&read.Level<=100&&read.ReadAt.Year>=2020&&read.ReadAt.ToUniversalTime()<=now){r.Level=read.Level;r.ReadAt=read.ReadAt.ToUniversalTime();r.Failed=false;r.Failures=0;r.Next=now.AddSeconds(30);SaveBatteries();}else{r.Failed=true;r.Next=now.AddSeconds(Math.Min(60,10*Math.Pow(2,Math.Min(3,r.Failures++))));if(read!=null&&(read.Status=="no-battery-service"||read.Status=="paired-device-not-found"))r.Next=now.AddMinutes(5);}}
   if(inventory==null)return; TickSignals(now);
   foreach(var source in phones.Sources){var phone=inventory.BluetoothDevices.FirstOrDefault(d=>d.Address==PhoneService.Address(source.Id));if(phone==null||String.IsNullOrEmpty(phone.ContainerId))continue;string key=(phone.Address+"|"+phone.ContainerId).ToUpperInvariant();BatteryRecord r;if(!batteries.TryGetValue(key,out r)){r=new BatteryRecord{Key=key};batteries[key]=r;}if(!settings.Test&&r.Pending==null&&now>=r.Next&&batteries.Values.Count(b=>b.Pending!=null)<3)r.Pending=PhoneBattery.ReadPairedAsync(phone.ContainerId);if(phone.CachedBattery>=0)r.Cached=phone.CachedBattery;BatteryGauge[] views;if(batteryViews.TryGetValue(source.Id,out views)){views[0].Level=r.Level>=0?r.Level:r.Cached;views[0].ToolTip=r.Level>=0?L("更新于 ","Updated ")+r.ReadAt.ToLocalTime().ToString("HH:mm:ss")+((r.Failed||(now-r.ReadAt).TotalSeconds>90)?L(" · 数据已过期"," · Stale"):""):r.Cached>=0?L("Windows 缓存，更新时间未知","Windows cache; timestamp unknown"):BatteryUnavailable(r.LastStatus);}}
   var readings=monitor.Snapshot();var nearby=AirBridge.PodMatcher.Pick(readings,settings.Text("PodAddress"),"AirPods",now);if(nearby==null)proximityCandidate="";else{if(proximityCandidate!=nearby.Address){proximityCandidate=nearby.Address;proximityAt=now;}if((now-proximityAt).TotalSeconds>=3){var matches=inventory.Devices.Where(d=>!Ignored(d.Id)&&providers.Resolve(d).Model==nearby.Model).ToArray();if(matches.Length==1){DateTime seen;if(!podSeen.TryGetValue(matches[0].Id,out seen))seen=now.AddMinutes(-1);if(settings.Bool("CasePopup")&&nearby.LidOpen&&(now-seen).TotalSeconds>45)Popup(nearby.Model,L("可能开盒 · 附近广播估计","Possible open case · nearby estimate"));podSeen[matches[0].Id]=now;}}}var defaultOutput=inventory.Endpoints.FirstOrDefault(e=>e.IsDefault);var selected=AirBridge.PodMatcher.Pick(readings,settings.Text("PodAddress"),defaultOutput==null?"":defaultOutput.Name,now);var currentPodDevice=inventory.Devices.FirstOrDefault(d=>d.IsDefault&&d.IsActive&&!Ignored(d.Id)&&providers.Resolve(d).ProviderId=="apple-airpods");if(currentPodDevice!=null){string model=providers.Resolve(currentPodDevice).Model;if(inventory.Devices.Count(d=>!Ignored(d.Id)&&providers.Resolve(d).Model==model)==1){var pairedReading=WearAdvertisements.Select(readings,model,now);if(pairedReading!=null)selected=pairedReading;}}if(selected==null)batteryCandidate="";else if(batteryCandidate!=selected.Address){batteryCandidate=selected.Address;batteryCandidateAt=now;}if((now-batteryCandidateAt).TotalSeconds<3)selected=null;foreach(var d in inventory.Devices){BatteryGauge[] views;if(!batteryViews.TryGetValue(d.Id,out views)||phones.Sessions.ContainsKey(d.Id))continue;int[] levels;if(!deviceLevels.TryGetValue(d.Id,out levels)){levels=new[]{-1,-1,-1};deviceLevels[d.Id]=levels;}var profile=providers.Resolve(d);var pod=d.IsDefault&&selected!=null&&(selected.Model==profile.Model||(profile.EvidenceEn??"").Contains("unconfirmed"))?selected:null;
    DateTime[] times;if(!deviceBatteryTimes.TryGetValue(d.Id,out times)){times=new DateTime[3];deviceBatteryTimes[d.Id]=times;}
    if(pod!=null){int[] next={pod.Left,pod.Right,pod.Case};DateTime[] at={pod.LeftAt,pod.RightAt,pod.CaseAt};for(int i=0;i<3;i++)if(next[i]>=0&&at[i]>times[i]){levels[i]=next[i];times[i]=at[i];headsetCacheDirty=true;}}
    if(d.Battery>=0)systemLevels[d.Id]=d.Battery;if(views.Length==1){int system;if(systemLevels.TryGetValue(d.Id,out system))levels[0]=system;views[0].Level=levels[0];}else for(int i=0;i<views.Length;i++){views[i].Visibility=Visibility.Visible;views[i].Label=i==0?L("左","L"):i==1?L("右","R"):L("盒","Case");views[i].Level=levels[i];views[i].Estimate=true;views[i].Charging=pod!=null&&(i==0?pod.LeftCharging:i==1?pod.RightCharging:pod.CaseCharging);views[i].ToolTip=times[i]==DateTime.MinValue?L("尚未读到有效广播电量","No valid battery advertisement yet"):L("广播估计 · 更新于 ","Broadcast estimate · Updated ")+times[i].ToLocalTime().ToString("MM-dd HH:mm:ss")+((now-times[i]).TotalSeconds>90?L(" · 数据已过期"," · Stale"):"");}
    if(views.Length>1&&levels.All(n=>n<0)&&systemLevels.ContainsKey(d.Id)){views[0].Label="";views[0].Level=systemLevels[d.Id];views[0].Estimate=false;views[0].ToolTip=L("Windows 设备总电量，更新时间未知","Windows total battery; timestamp unknown");for(int i=1;i<views.Length;i++)views[i].Visibility=Visibility.Collapsed;}
    int level=levels.Take(views.Length==1?1:2).Where(n=>n>=0).DefaultIfEmpty(-1).Min();if(level>20)lowWarned.Remove(d.Id);if(pod!=null&&times.Take(2).Any(t=>(now-t).TotalSeconds<=90)&&settings.Bool("LowBattery")&&level>=0&&level<=10&&lowWarned.Add(d.Id))Popup(profile.Model,L("电量低：","Low battery: ")+level+"%");
   }
   SaveHeadsetBatteries(now);
  }
 }
}

